WITH with_dims AS (SELECT a.id, a.account_id, a.txn_type, a.txn_time, a.is_flagged, d.opened_date, d.account_type, d.balance FROM transactions a LEFT JOIN accounts d ON a.account_id = d.id) SELECT account_id, DATE_TRUNC('WEEK', txn_time) AS week_start, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, AVG(balance) AS avg_balance, MIN(balance) AS min_balance, MIN(txn_time) AS first_seen FROM with_dims GROUP BY GROUPING SETS ((account_id, DATE_TRUNC('WEEK', txn_time)), (account_id))
